package com.nexushr.entity; import jakarta.persistence.*; import java.time.*; import java.util.UUID;
@Entity @Table(name="holidays") public class Holiday { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(nullable=false) private String name; @Column(nullable=false) private LocalDate date; private boolean optionalHoliday; public UUID getId(){return id;} public String getName(){return name;} public void setName(String v){name=v;} public LocalDate getDate(){return date;} public void setDate(LocalDate v){date=v;} public boolean isOptionalHoliday(){return optionalHoliday;} public void setOptionalHoliday(boolean v){optionalHoliday=v;} }
